<?php
declare(strict_types=1);
session_start();require_once __DIR__ . '/config/product_step12.php';
if(empty($_SESSION['product_payment_csrf']))$_SESSION['product_payment_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['product_payment_csrf'];
$error=null;$success=null;$sales=[];$payments=[];$selectedOrder=(int)($_GET['order']??$_POST['order_id']??0);
try{
 $pdo=business_db();product_step12_ensure($pdo);$ctx=product_step12_context($pdo);$orgId=(int)$ctx['organization_id'];
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$action=(string)($_POST['action']??'add');
  if($action==='add'){$amount=(float)($_POST['amount']??0);$date=(string)($_POST['payment_date']??date('Y-m-d'));$method=(string)($_POST['payment_method']??'other');$reference=trim((string)($_POST['reference_no']??''));$notes=trim((string)($_POST['notes']??''));$id=product_step12_add_payment($pdo,$selectedOrder,$date,$amount,$method,$reference,$notes);$success='Payment #'.$id.' recorded.';}
  elseif($action==='reverse'){$pid=(int)($_POST['payment_id']??0);product_step12_reverse_payment($pdo,$pid,trim((string)($_POST['reason']??'')));$success='Payment #'.$pid.' reversed with audit history preserved.';}
 }
 $sales=product_step12_sales_rows($pdo,$orgId,'active');foreach($sales as &$s){$s['payment_state']=product_step12_sync_payment_status($pdo,(int)$s['order_id']);}unset($s);
 $stmt=$pdo->prepare("SELECT p.*,q.quote_code,q.customer_name,m.full_name member_name FROM product_sale_payments p JOIN product_sale_ledger l ON l.id=p.sale_ledger_id AND l.organization_id=p.organization_id JOIN orders o ON o.id=p.order_id AND o.organization_id=p.organization_id LEFT JOIN product_quotes q ON q.id=l.quote_id AND q.organization_id=l.organization_id LEFT JOIN members m ON m.id=o.member_id AND m.organization_id=o.organization_id WHERE p.organization_id=? ORDER BY p.payment_date DESC,p.id DESC LIMIT 200");$stmt->execute([$orgId]);$payments=$stmt->fetchAll();
}catch(Throwable $e){$error=$e->getMessage();}
function ppay_money(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?>
