<header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 12 • Product Sale Payments</small></span></a><div class="os-top-actions"><a class="os-btn" href="product_sales_center.php">Sales</a><a class="os-btn" href="product_cost_center.php">Cost Basis</a><a class="os-btn primary" href="product_sales_analytics.php">Analytics</a></div></div></header>
<div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">STEP 12</div><nav class="os-nav"><a href="product_sales_center.php"><i class="dot"></i>Sales Center</a><a href="product_cost_center.php"><i class="dot"></i>Cost Basis</a><a class="active" href="product_payments.php"><i class="dot"></i>Payments</a><a href="product_sales_analytics.php"><i class="dot"></i>Sales Analytics</a><a href="step12_audit.php"><i class="dot"></i>STEP 12 Audit</a></nav><div class="os-sidebar-status"><b>Collection tracking only</b><span>Payments do not create duplicate Income entries automatically.</span></div></aside>
<main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 12D • PAYMENT COLLECTION</div><h1>Track actual money received against finalized product sales.</h1><p>Payments are separate from order revenue, so recording a payment never double-counts income. Reversal changes payment status but preserves the original evidence.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'PAYMENTS CENTER LIVE':'Review required' ?></span><span class="os-chip"><?= count($sales) ?> active sales</span><span class="os-chip"><?= count($payments) ?> payment records</span></div></section>
<?php if($error):?><div class="pp-alert bad"><strong>Payment diagnostic:</strong> <?= product_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Saved:</strong> <?= product_h($success) ?></div><?php endif;?>
<?php if(!$error):?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-5"><h2>Add Payment</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= product_h($csrf) ?>"><input type="hidden" name="action" value="add"><label>Active Product Sale<select name="order_id" required><option value="">Choose sale…</option><?php foreach($sales as $s):$st=$s['payment_state'];?><option value="<?= (int)$s['order_id'] ?>" <?= (int)$s['order_id']===$selectedOrder?'selected':'' ?>>Order #<?= (int)$s['order_id'] ?> • <?= product_h($s['quote_code']?:'Product Sale') ?> • <?= product_h($s['member_name']?:$s['customer_name']?:'Customer') ?> • Due <?= ppay_money($st['outstanding']) ?></option><?php endforeach;?></select></label><label>Payment Date<input type="date" name="payment_date" value="<?= product_h(date('Y-m-d')) ?>" required></label><label>Amount<input type="number" name="amount" min="0.01" step="0.01" required></label><label>Method<select name="payment_method"><option value="cash">Cash</option><option value="upi">UPI</option><option value="bank">Bank Transfer</option><option value="card">Card</option><option value="other">Other</option></select></label><label>Reference No.<input name="reference_no" maxlength="120" placeholder="Optional transaction/reference"></label><label>Notes<textarea name="notes" rows="2"></textarea></label><button>Record Payment →</button></form></article>
<article class="os-card pp-span-7"><h2>Collection Status</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Order</th><th>Customer</th><th>Sale Total</th><th>Paid</th><th>Outstanding</th><th>Status</th></tr></thead><tbody><?php foreach($sales as $s):$st=$s['payment_state'];?><tr><td><a href="product_sale_detail.php?order=<?= (int)$s['order_id'] ?>"><b>#<?= (int)$s['order_id'] ?></b></a><small><?= product_h($s['quote_code']?:'') ?></small></td><td><?= product_h($s['member_name']?:$s['customer_name']?:'—') ?></td><td><?= ppay_money($st['due']) ?></td><td><?= ppay_money($st['paid']) ?></td><td><?= ppay_money($st['outstanding']) ?></td><td><span class="pp-badge"><?= product_h(strtoupper($st['status'])) ?></span></td></tr><?php endforeach;?><?php if(!$sales):?><tr><td colspan="6">No active finalized product sales yet.</td></tr><?php endif;?></tbody></table></div></article></section>
<section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2>Payment History</h2><p>Reversed payments remain visible; no hard delete.</p></div></div><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>Payment</th><th>Order</th><th>Customer</th><th>Amount</th><th>Method</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?= product_h($p['payment_date']) ?></td><td>#<?= (int)$p['id'] ?></td><td><a href="product_sale_detail.php?order=<?= (int)$p['order_id'] ?>">#<?= (int)$p['order_id'] ?></a></td><td><?= product_h($p['member_name']?:$p['customer_name']?:'—') ?></td><td><?= ppay_money($p['amount']) ?></td><td><?= product_h(strtoupper($p['payment_method'])) ?><?= $p['reference_no']?'<small>'.product_h($p['reference_no']).'</small>':'' ?></td><td><span class="pp-badge <?= $p['status']==='active'?'':'warn' ?>"><?= product_h(strtoupper($p['status'])) ?></span></td><td><?php if($p['status']==='active'):?><details><summary>Reverse</summary><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= product_h($csrf) ?>"><input type="hidden" name="action" value="reverse"><input type="hidden" name="payment_id" value="<?= (int)$p['id'] ?>"><input name="reason" minlength="5" placeholder="Reason" required><button>Confirm</button></form></details><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="8">No payment records yet.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?>
<div class="os-footer-note"><strong>Payment rule:</strong> active payments cannot exceed the sale outstanding amount. Payment reversal is audited and recalculates Unpaid/Partial/Paid status.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
